#include <stdio.h>

int main(void) {
    int diem;
    scanf("%d", &diem);
    if (diem < 0 || diem > 10)
        printf("khong hop le\n");
    else if (diem <= 4)
        printf("kem\n");
    else if (diem <= 6)
        printf("trung binh\n");
    else if (diem <= 8)
        printf("kha\n");
    else
        printf("gioi\n");
    return 0;
}
